(2904,0,0,'Hearthglen?? But...\n',0,1,1,2905,0,0,0,'',0),
(2905,0,0,'I will take you up on that offer, Eitrigg.',0,1,1,2906,0,0,0,'',0),
(2906,0,0,'Ah, so that is how they pushed the Dark Iron to the lower parts of the Spire.',0,1,1,2907,0,0,0,'',0),
